const themes=['Identity continuity','First-day readiness','Remote onboarding','Shared-device access','Access governance','Offboarding evidence'];
export function homePage(){return `<div class="home-shell"><header class="home-header"><a href="#home" aria-label="MajorKey workshop home"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="180" height="32"></a><span>IDENTITY EXPERIENCE STUDIO</span><button class="quiet studio-prep" data-action="ready">Presenter preparation</button><button class="quiet" data-action="agenda">Workshop agenda ↗</button></header><main class="home-main">${studioOpening}<div class="home-section-heading"><h2>Every identity has a story.</h2><span>Choose a persona → Story → Architecture → Live demo</span></div><section class="home-personas" aria-label="Choose a persona">${people.map((p,i)=>`<article class="home-persona" style="--persona-tone:${['#20f593','#c398ff','#77ddcb','#b9b1ff','#f0c994','#83c5ff'][i]}"><div class="home-card-top"><span class="home-avatar">${p.initials}</span><span class="home-topic">${themes[i]}</span><span class="home-card-arrow" aria-hidden="true">↗</span></div><h3>${p.name}</h3><div class="home-job">${p.job}</div><h4>${p.role}</h4><p>${p.intro}</p><div class="home-card-foot"><span>${p.moments.length} story moments</span>${['nadia','sam','tom'].includes(p.id)?'<span>External ID lens included</span>':''}</div><div class="home-card-actions"><button class="primary" data-action="person" data-value="${i}">Explore story →</button><button class="outline" data-action="person-ai" data-value="${i}">✦ How AI helps</button></div></article>`).join('')}</section><section class="external-journey-section" aria-labelledby="external-journeys-title"><div class="external-journey-heading"><div><span class="eyebrow">MICROSOFT ENTRA EXTERNAL ID</span><h2 id="external-journeys-title">Two external identities. Two business boundaries.</h2></div><p>Choose a guided customer or partner journey, then move through its experience, architecture and evidence.</p></div><div class="external-journey-grid"><article class="vendor-feature"><div><div class="eyebrow">VENDOR COORDINATION</div><h3>Lena Fischer · from first visit to useful access</h3><p>Branded onboarding, vendor verification, property assignments, recovery and work-order authorization.</p></div><a class="outline" href="#lena/experience">Explore vendor journey →</a></article><article class="vendor-feature franchise-feature"><div><div class="eyebrow">FRANCHISE OPERATIONS · NEW</div><h3>Maya Chen · grow the network, keep every boundary</h3><p>Business verification, location-scoped authority, step-up, delegation, transfer and audit evidence.</p></div><a class="outline" href="#maya/experience">Explore franchise journey →</a></article></div></section><footer class="home-footer"><span>MajorKey · Harborline reference lab · Azure edition</span><div><button class="quiet" data-action="catalog">Browse 34 use cases</button><button class="quiet" data-action="ready">Presenter preparation</button></div></footer></main></div><dialog id="modal" aria-labelledby="modal-title"></dialog>`;}
